    )])
    .expect("task definition");
    let mut m = delivery();
    m.profile = "task".to_owned();
    m.atoms.push(atom(15, "task.checklist"));
    assert!(matches!(
        m.validate_in(Some("OW"), &registry),
        Err(ManifestError::WorkingFormProfile { .. })
    ));
}

