#[test]
fn unknown_optional_namespaced_role_is_preserved() {
    let mut m = delivery();
    m.atoms.push(AtomEntry {
        ordinal: 55,
        role: "lab.protocol".to_owned(),
        path: Some("atoms/55-lab.md".to_owned()),
        r#ref: None,
        required: false,
